# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Timekeeping::LocalOwner service callers" do
  it "local owner refuses unauthorised callers on every reservation route and writes nothing" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    company = create(:company)
    other_company = create(:company)
    project = create(:project, client: create(:client, company_id: company.id))
    user = create(:user)
    entry = Timekeeping::LocalEntry.create!(company_id: company.id, project_id: project.id, user_id: user.id,
                                            work_date: Date.new(2026, 3, 2), duration: 60.0, bill_status: "unbilled",
                                            agent_id: 77)
    granted = %w[reservations.prepare reservations.commit reservations.abort invoices.mark_billed agents.detach_entries]
    actor_class = Timekeeping::LocalOwner::Actor
    generation = TimekeepingOwnership.current.generation.to_s
    tables = %w[reservations invoice_operations service_idempotency_receipts entry_audits entry_outbox_items]
    snapshot = lambda do
      counts = tables.index_with { |table| ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
      counts.merge("entry" => Timekeeping::LocalEntry.find(entry.id).attributes.slice("version", "bill_status", "agent_id"))
    end
    params_for = lambda do |operation|
      body = { "operation_id" => SecureRandom.uuid, "invoice_id" => 501, "disposition" => "active", "entries" => [entry.id] }
      { "body" => body, "invoice_id" => 501, "agent_id" => 77 }.tap { |params| params.delete("agent_id") unless operation == :detach_entries }
    end
    before = snapshot.call

    # "A nil actor answers `unauthorized`. A user actor, or a service without the operation, answers `forbidden`.
    # A service bound to another company answers `not_found`."
    expected = [
      [nil, 401, "unauthorized"],
      [actor_class.user(user_id: user.id, role: "owner"), 403, "forbidden"],
      [actor_class.service(name: "reporting", company_id: company.id, operations: []), 403, "forbidden"],
      [actor_class.service(name: "invoice-boundary", company_id: other_company.id, operations: granted), 404, "not_found"]
    ]

    %i[prepare commit abort mark_billed detach_entries].each do |operation|
      expected.each do |actor, status, reason|
        outcome = Timekeeping::LocalOwner.call(operation:, company_id: company.id, generation:, actor:,
                                               params: params_for.call(operation))

        expect([operation, outcome.status, outcome.body]).to eq([operation, status, { "reason" => reason }])
      end
    end
    expect(snapshot.call).to eq(before)
  end
end

RSpec.describe "Timekeeping::LocalOwner service request shapes" do
  # The local owner answers these bodies as Timekeeping's ReservationRequest does: a credential in the body is
  # credential_in_body, a duplicate entry or an id beyond bigint is invalid_request, and a command path id that
  # cannot name a row is not_found. None of them writes a row.
  around { |example| with_timekeeping_service_token { example.run } }

  it "refuses a credential in the body, a repeated entry, an over-range id and an unusable command path id" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    company = create(:company)
    project = create(:project, client: create(:client, company_id: company.id))
    user = create(:user)
    entry = Timekeeping::LocalEntry.create!(company_id: company.id, project_id: project.id, user_id: user.id,
                                            work_date: Date.new(2026, 3, 2), duration: 60.0, bill_status: "unbilled")
    service = Timekeeping::LocalOwner::Actor.service(
      name: "invoice-boundary", company_id: company.id, operations: TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS
    )
    generation = TimekeepingOwnership.current.generation.to_s
    tables = %w[reservations invoice_operations service_idempotency_receipts entry_audits entry_outbox_items]
    counts = -> { tables.index_with { |table| ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i } }
    prepare_body = lambda do |overrides|
      { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "disposition" => "active",
        "entries" => [entry.id] }.merge(overrides)
    end
    over_range = 2**63
    before = counts.call

    cases = [
      [:prepare, { "body" => prepare_body.call("note" => ENV.fetch(Internal::V1::BaseController::SERVICE_TOKEN_ENV)) },
       422, "credential_in_body"],
      [:prepare, { "body" => prepare_body.call("entries" => [entry.id, entry.id]) }, 400, "invalid_request"],
      [:prepare, { "body" => prepare_body.call("entries" => [over_range]) }, 400, "invalid_request"],
      [:commit, { "body" => { "invoice_id" => over_range, "operation_id" => SecureRandom.uuid } }, 400, "invalid_request"],
      [:mark_billed, { "invoice_id" => over_range.to_s, "body" => { "operation_id" => SecureRandom.uuid } }, 404, "not_found"],
      [:detach_entries, { "agent_id" => "abc", "body" => { "operation_id" => SecureRandom.uuid } }, 404, "not_found"]
    ]

    cases.each do |operation, params, status, reason|
      outcome = Timekeeping::LocalOwner.call(operation:, company_id: company.id, generation:, actor: service, params:)

      expect([operation, outcome.status, outcome.body]).to eq([operation, status, { "reason" => reason }])
    end
    expect(counts.call).to eq(before)
  end
end

RSpec.describe "Timekeeping::LocalOwner service callers across companies" do
  it "local owner never replays a stored service answer to another company's service using the same operation id" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    company = create(:company)
    other_company = create(:company)
    project = create(:project, client: create(:client, company_id: company.id))
    user = create(:user)
    entry = Timekeeping::LocalEntry.create!(company_id: company.id, project_id: project.id, user_id: user.id,
                                            work_date: Date.new(2026, 3, 2), duration: 60.0, bill_status: "unbilled")
    granted = %w[reservations.prepare reservations.commit reservations.abort invoices.mark_billed agents.detach_entries]
    actor_class = Timekeeping::LocalOwner::Actor
    owner_service = actor_class.service(name: "invoice-boundary", company_id: company.id, operations: granted)
    # Same service name and grants, bound to another company.
    foreign_service = actor_class.service(name: "invoice-boundary", company_id: other_company.id, operations: granted)
    generation = TimekeepingOwnership.current.generation.to_s
    operation_id = SecureRandom.uuid
    prepare_params = { "body" => { "operation_id" => operation_id, "invoice_id" => 501, "disposition" => "active",
                                   "entries" => [entry.id] } }
    commit_params = { "body" => { "operation_id" => operation_id, "invoice_id" => 501 } }

    expect(Timekeeping::LocalOwner.call(operation: :prepare, company_id: company.id, generation:, actor: owner_service,
                                        params: prepare_params).status).to eq(200)
    committed = Timekeeping::LocalOwner.call(operation: :commit, company_id: company.id, generation:, actor: owner_service,
                                             params: commit_params)
    expect(committed.status).to eq(200)

    # "A service bound to another company answers `not_found`."
    # The foreign service names the first company's id, so a lookup that skipped the company check would find the
    # stored operation and receipt.
    %i[prepare commit].zip([prepare_params, commit_params]).each do |operation, params|
      outcome = Timekeeping::LocalOwner.call(operation:, company_id: company.id, generation:, actor: foreign_service,
                                             params:)

      expect([operation, outcome.status, outcome.body]).to eq([operation, 404, { "reason" => "not_found" }])
    end
    expect(ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM service_idempotency_receipts").to_i).to eq(1)
  end
end
